import { Component, Host, Prop, h } from "@stencil/core";
import { user } from "../../../icons/index";

/**
 * @status beta
 * @description Avatars are used to represent a user. They can display an image, initials, or an icon.
 *
 * @part base - The base wrapper for the avatar.
 * @part image - The img element when an image is provided.
 * @part initials - The span element for the initials.
 * @part icon - The icon element.
 */
@Component({
	tag: "hbr-avatar",
	styleUrl: "avatar.scss",
	shadow: true,
})
export class Avatar {
	/** Describes the avatar for accessibility purposes. */
	@Prop() aria: { label: string } = { label: "User avatar" };

	/** Controls the image source. */
	@Prop() image?: string;

	/** Determines which size of avatar will be used. */
	@Prop({ reflect: true }) size?: "small" | "medium" | "large" = "medium";

	/** Controls the initials that are shown in the avatar. */
	@Prop() initials?: string;

	/** Controls the loading behavior of the image. */
	@Prop() loading?: "eager" | "lazy" = "eager";

	/** Controls the shape of the avatar. */
	@Prop() shape?: "square" | "circle" | "rounded" = "circle";

	render() {
		let content: JSX.Element;
		if (this.image) {
			content = (
				<img
					part="image"
					class={"avatar__image"}
					src={this.image}
					loading={this.loading}
					alt={this.aria.label}
				/>
			);
		} else if (this.initials) {
			content = (
				<div part="initials" class={"avatar__initials"}>
					{this.initials}
				</div>
			);
		} else {
			content = (
				<div part="icon" class={"avatar__icon"} aria-hidden="true">
					<slot name="icon">
						<hbr-icon asset={user} />
					</slot>
				</div>
			);
		}

		return (
			<Host>
				<div
					part="base"
					class={{
						avatar: true,
						[`avatar__${this.shape}`]: true,
					}}
					role="img"
					aria-label={this.aria.label}
				>
					{content}
				</div>
			</Host>
		);
	}
}
